#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    // Place elements one by one: place value (target+1) at position target
    for(int target=0; target<n; target++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        // Move element from pos to target using at most 2 operations
        // First, move element to position 0 (if not already there)
        if(pos != 0){
            // Use x=pos, y=1, but need x+y<n => pos+1<n => pos<n-1
            // suffix=[p[n-1]], middle=[p[pos..n-2]], prefix=[p[0..pos-1]]
            // result: p[n-1], p[pos..n-2], p[0..pos-1]
            // Element at pos goes to position 1. Not 0.

            // Use x=1, y=n-pos: need 1+n-pos<n => pos>1
            // suffix=[p[pos..n-1]], middle=[p[1..pos-1]], prefix=[p[0]]
            // Element at pos goes to position 0. 
            if(pos > 1){
                doOp(1, n-pos);
            } else {
                // pos==1: use x=1,y=1 if n>2: moves p[n-1] to front, p[0] to back, element at 1 stays at 1
                // Instead: x=2, y=n-2: need 2+n-2<n => 0<0, invalid if exact
                // x=1, y=n-2: element at 1 goes to pos 1-1+n-2=n-2. Then recurse.
                // Simpler: swap with x=pos+1=2, y=n-2 invalid. Use x=1,y=1 => element at 0 goes to n-1, element at n-1 goes to 0, element at 1 stays at 1... 
                // For pos=1: x=1, y=n-1 => x+y=n invalid. x=1,y=n-2 => element at 1 goes to n-2.
                doOp(1, n-2); // element at pos=1 goes to position n-2
                doOp(1, n-(n-2)); // = doOp(1,2), element at n-2 goes to 0
            }
            pos=0;
        }
        // Now element is at position 0, move to target
        if(target > 0 && target < n-1){
            doOp(target, n-target-1);
            // Element at 0 goes to n-target+0 = n-target. Hmm, that's not target.
            // prefix goes to end: pos 0 -> n-target
            // Use x=1, y=n-1-target: element at 0 goes to n-1-(n-1-target)=n-1-n+1+target=target. Wait:
            // pos 0 < x=1: new pos = n-1+0 = n-1. No: n - x + i = n-1+0=n-1.
            doOp(1, n-1-target);
        } else if(target==n-1){
            doOp(1,1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
